#include <bits/stdc++.h>
using namespace std;

void solve(){
    int n; cin>>n;
    vector<int> a(n);
    for(int i=0;i<n;i++){cin>>a[i];}
    
    vector<int> diff;
    for(int i=0;i<n;i++){
        int x=abs(a[i]-a[(i+1)%n]);
        int y;
        if(i==0){ y=abs(a[i]-a[n-1]);}
        else{ y=abs(a[i]-a[(i-1)%n]);}
        diff.push_back(max(x,y));
    }
    cout<<*min_element(diff.begin(), diff.end())<<"\n";

   
}

int main() {
	int t; cin>>t;
	while(t--){
	    solve();
	}
}
